// =====================================================
// 66-cylinder Modbus TCP simulator
// Each cylinder = 58 Holding Registers
// Total = 66 * 58 = 3828 registers (address 0..3827)
//
// Input:
//   Timer inject: updates all cylinders every second
//   Fault inject: msg.payload = {
//       "cylinder_id": 5,
//       "cylinder_fault": "SLOW" | "NORMAL",
//       "ratio": 3
//   }
//
// Register layout per cylinder (offset from cylinder base):
//   0..3   timestamp_DI_IPos_ON       ULINT
//   4..7   timestamp_DI_IPos_OFF      ULINT
//   8..11  timestamp_DI_EPos_ON       ULINT
//   12..15 timestamp_DI_EPos_OFF      ULINT
//   16..19 timestamp_DO_MCtrl12_ON    ULINT
//   20..23 timestamp_DO_MCtrl12_OFF   ULINT
//   24..27 timestamp_DO_MCtrl14_ON    ULINT
//   28..31 timestamp_DO_MCtrl14_OFF   ULINT
//   32..33 udiCycleCounter            UDINT
//   34..57 sPartnumber                STRING[48], 24 WORDs
//
// Data order: high WORD first (Big Endian).
// STRING: 48 bytes, two ASCII/UTF-8 bytes per WORD, high byte first.
// =====================================================

const CYLINDER_COUNT = 66;
const REG_PER_CYLINDER = 58;
const TOTAL_REGISTERS = CYLINDER_COUNT * REG_PER_CYLINDER;

const BASE = {
    ipos_off: 15,
    epos_on: 50,
    ctrl: 65,
    epos_off: 80,
    ipos_on: 110
};

// ---------- Handle manual fault command ----------
let faults = flow.get("cylinder_faults") || {};

let command = msg.payload;
if (typeof command === "string") {
    try { command = JSON.parse(command); } catch (e) {}
}

if (command && typeof command === "object" &&
    command.cylinder_id !== undefined) {

    const id = Number(command.cylinder_id);

    if (Number.isInteger(id) && id >= 1 && id <= CYLINDER_COUNT) {
        const requestedFault = String(command.cylinder_fault || "NORMAL").toUpperCase();
        const ratio = Number(command.ratio);

        faults[id] = {
            fault: requestedFault === "SLOW" ? "SLOW" : "NORMAL",
            ratio: Number.isFinite(ratio) && ratio > 0 ? ratio : 3
        };

        flow.set("cylinder_faults", faults);
    }
}

// ---------- Cycle counters ----------
let counters = flow.get("cylinder_counters");
if (!Array.isArray(counters) || counters.length !== CYLINDER_COUNT) {
    counters = Array(CYLINDER_COUNT).fill(0);
}

// ---------- Helpers ----------
function putU64(registers, start, value) {
    // Date.now() is currently a safe integer; convert via string to BigInt.
    let v = BigInt(String(Math.trunc(value)));
    for (let word = 0; word < 4; word++) {
        const shift = BigInt(48 - word * 16);
        registers[start + word] = Number((v >> shift) & 0xFFFFn);
    }
}

function putU32(registers, start, value) {
    const v = BigInt(value) & 0xFFFFFFFFn;
    registers[start] = Number((v >> 16n) & 0xFFFFn);
    registers[start + 1] = Number(v & 0xFFFFn);
}

function putString48(registers, start, value) {
    // Siemens STRING[48] in the supplied table is treated as 48 data bytes.
    // Part numbers are ASCII, so one character = one byte.
    const buf = Buffer.alloc(48, 0);
    const source = Buffer.from(String(value), "ascii");
    source.copy(buf, 0, 0, 48);

    for (let i = 0; i < 24; i++) {
        registers[start + i] = (buf[i * 2] << 8) | buf[i * 2 + 1];
    }
}

function random0to5() {
    return Math.floor(Math.random() * 6);
}

// ---------- Build 3828 Holding Registers ----------
const registers = new Array(TOTAL_REGISTERS).fill(0);
const now = Date.now();

for (let i = 0; i < CYLINDER_COUNT; i++) {
    const cylinderId = i + 1;
    const baseReg = i * REG_PER_CYLINDER;

    counters[i] = (Number(counters[i]) || 0) + 1;

    const config = faults[cylinderId] || { fault: "NORMAL", ratio: 3 };
    const slow = config.fault === "SLOW";
    const ratio = slow ? (Number(config.ratio) || 3) : 1;

    const timestamps = {
        timestamp_DI_IPos_ON:
            now + Math.round(BASE.ipos_on * ratio) + random0to5(),

        timestamp_DI_IPos_OFF:
            now + Math.round(BASE.ipos_off * ratio) + random0to5(),

        timestamp_DI_EPos_ON:
            now + Math.round(BASE.epos_on * ratio) + random0to5(),

        timestamp_DI_EPos_OFF:
            now + Math.round(BASE.epos_off * ratio) + random0to5(),

        timestamp_DO_MCtrl12_ON:
            now + Math.round(BASE.ctrl * ratio),

        timestamp_DO_MCtrl12_OFF:
            now,

        timestamp_DO_MCtrl14_ON:
            now,

        timestamp_DO_MCtrl14_OFF:
            now + Math.round(BASE.ctrl * ratio)
    };

    let r = baseReg;

    putU64(registers, r, timestamps.timestamp_DI_IPos_ON); r += 4;
    putU64(registers, r, timestamps.timestamp_DI_IPos_OFF); r += 4;
    putU64(registers, r, timestamps.timestamp_DI_EPos_ON); r += 4;
    putU64(registers, r, timestamps.timestamp_DI_EPos_OFF); r += 4;
    putU64(registers, r, timestamps.timestamp_DO_MCtrl12_ON); r += 4;
    putU64(registers, r, timestamps.timestamp_DO_MCtrl12_OFF); r += 4;
    putU64(registers, r, timestamps.timestamp_DO_MCtrl14_ON); r += 4;
    putU64(registers, r, timestamps.timestamp_DO_MCtrl14_OFF); r += 4;

    putU32(registers, r, counters[i]); r += 2;

    const partNumber = "CYL-" + String(cylinderId).padStart(3, "0");
    putString48(registers, r, partNumber);
}

flow.set("cylinder_counters", counters);

const slowCount = Object.keys(faults)
    .filter(id => faults[id] && faults[id].fault === "SLOW").length;

node.status({
    fill: slowCount > 0 ? "yellow" : "green",
    shape: "dot",
    text: `${CYLINDER_COUNT} cylinders | ${slowCount} slow faults | ${TOTAL_REGISTERS} HR`
});

// Flex Server's holding-register buffer uses an 8-byte slot per register.
// Place each 16-bit value (high byte first) at the start of its slot.
// Passing `registers` directly would truncate each word to one byte and pack
// the values at the wrong offsets.
const flexBytes = new Array(TOTAL_REGISTERS * 8).fill(0);
for (let i = 0; i < registers.length; i++) {
    const value = registers[i] & 0xFFFF;
    const offset = i * 8;
    flexBytes[offset] = (value >> 8) & 0xFF;
    flexBytes[offset + 1] = value & 0xFF;
}

msg.payload = {
    value: flexBytes,
    register: "holding",
    address: 0,
    disableMsgOutput: 1
};

return msg;

funcGetCoil:
function getFlexCoil(addr, unitID) {
    if (unitID === node.unitId &&
        addr >= node.minAddress &&
        addr <= node.splitAddress) {
        return node.coils.readUInt8(addr * node.bufferFactor);
    }
}

funcGetDiscreteInput:
function getFlexDiscreteInput(addr, unitID) {
    addr += node.splitAddress;
    if (unitID === node.unitId &&
        addr >= node.splitAddress &&
        addr <= node.splitAddress * 2) {
        return node.coils.readUInt8(addr * node.bufferFactor);
    }
}

funcGetInputRegister:
function getFlexInputRegister(addr, unitID) {
    if (unitID === node.unitId &&
        addr >= node.minAddress &&
        addr <= node.splitAddress) {
        return node.registers.readUInt16BE(addr * node.bufferFactor);
    }
}

funcGetHoldingRegister:
function getFlexHoldingRegister(addr, unitID) {
    addr += node.splitAddress;
    if (unitID === node.unitId &&
        addr >= node.splitAddress &&
        addr <= node.splitAddress * 2) {
        return node.registers.readUInt16BE(addr * node.bufferFactor);
    }
}

funcSetCoil:
function setFlexCoil(addr, value, unitID) {
    if (unitID === node.unitId &&
        addr >= node.minAddress &&
        addr <= node.splitAddress) {
        node.coils.writeUInt8(value, addr * node.bufferFactor);
    }
}

funcSetRegister:
function setFlexRegister(addr, value, unitID) {
    addr += node.splitAddress;
    if (unitID === node.unitId &&
        addr >= node.splitAddress &&
        addr <= node.splitAddress * 2) {
        node.registers.writeUInt16BE(value, addr * node.bufferFactor);
    }
}
